impl Solution{pub fn generate_palindromes(s:String)->Vec<String>{let mut c=[0usize;256];for b in s.bytes(){c[b as usize]+=1}let mut odd=0;let mut mid=None;let mut h=vec![];for i in 0..256{if c[i]%2==1{odd+=1;mid=Some(i as u8 as char)}for _ in 0..c[i]/2{h.push(i as u8 as char)}}if odd>1{return vec![]}fn f(h:&[char],u:&mut Vec<bool>,cur:&mut Vec<char>,mid:Option<char>,o:&mut Vec<String>){if cur.len()==h.len(){let mut s:String=cur.iter().collect();if let Some(m)=mid{s.push(m)}for &x in cur.iter().rev(){s.push(x)}o.push(s);return}for i in 0..h.len(){if u[i]||(i>0&&h[i]==h[i-1]&&!u[i-1]){continue}u[i]=true;cur.push(h[i]);f(h,u,cur,mid,o);cur.pop();u[i]=false;}}let mut o=vec![];f(&h,&mut vec![false;h.len()],&mut vec![],mid,&mut o);o}}
